//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_etn.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = 'ULDSTF41095_1.xml';
scwin.vInitTpCd = '0';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_Search
 * 설명       : 보증인 데이터를 조회한다.
 ***********************************************/
scwin.fn_Search = function() {
    var url = "/etn/EtnLstSprt.do?method=searchSrtyList";
    url += "&outputMessageId=ETN_SRTY_LIST";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&COM_NM=" + $c.stf.getObjectValue(txb_SrtyNm);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};


/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        fn_GetPar = prt.fn_GetPar;
        fn_SetPar = prt.fn_SetPar;
    }
    if (fn_GetPar != undefined) {
        var arrPar = new Array();
        fn_GetPar(arrPar);
        $c.stf.setObjectValue(txb_SrtyNm, arrPar[0].SRTY_CD);
        scwin.fn_Search();
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.txb_SrtyNm_onkeypress = function() {
    if (window.event.keyCode == 13) scwin.fn_Search();
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    //파라미터설정
    scwin.fn_SetParam();

    //목록조회
    /*
    dts_List.SyncLoad = true;
    dts_List.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BNS_INST_INFO";
    dts_List.Reset();
    dts_List.SyncLoad = false;
    */

    //fn_Search();

};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.grd_List_OnDblClick = async function(row, colid) {
    if (row > 0) {
        var arrPar = new Array();
        arrPar[0] = {
            SRTY_CD: dts_List.getCellData(row, "SRTY_CD"),
            SRTY_NM: dts_List.getCellData(row, "SRTY_NM")
        };
        fn_SetPar(arrPar);
        await $c.frame.CloseFrame();
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
